use std::collections::HashMap;

use anyhow::{Context, Result};
use zbus::zvariant::{self};

use crate::runner::{
    Runner, RunnerOpenFileOptions, RunnerResult, RunnerSaveFileOptions, RunnerSaveFilesOptions,
};

// types from https://github.com/pop-os/xdg-desktop-portal-cosmic/blob/41c1e7cfd0779db6005fc64798ac75b630332678/src/file_chooser.rs, thank you!

const PORTAL_RESPONSE_SUCCESS: u32 = 0;
const PORTAL_RESPONSE_CANCELLED: u32 = 1;
const PORTAL_RESPONSE_OTHER: u32 = 2;

#[derive(zvariant::Type)]
#[zvariant(signature = "(ua{sv})")]
enum PortalResponse<T: zvariant::Type + serde::Serialize> {
    Success(T),
    Cancelled,
    Other,
}

impl<T: zvariant::Type + serde::Serialize> serde::Serialize for PortalResponse<T> {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::Success(res) => (PORTAL_RESPONSE_SUCCESS, res).serialize(serializer),
            Self::Cancelled => (
                PORTAL_RESPONSE_CANCELLED,
                HashMap::<String, zvariant::Value>::new(),
            )
                .serialize(serializer),
            Self::Other => (
                PORTAL_RESPONSE_OTHER,
                HashMap::<String, zvariant::Value>::new(),
            )
                .serialize(serializer),
        }
    }
}

impl From<Result<FileChooserResult>> for PortalResponse<FileChooserResult> {
    fn from(res: Result<FileChooserResult>) -> Self {
        match res {
            Ok(res) => Self::Success(res),
            Err(err) => {
                tracing::error!("Error: {:?}", err);
                Self::Other
            }
        }
    }
}

pub type Choices = Vec<(String, String, Vec<(String, String)>, String)>;
pub type Filter = (String, Vec<(u32, String)>);
pub type Filters = Vec<Filter>;

#[derive(zvariant::DeserializeDict, zvariant::Type, Clone, Debug)]
#[zvariant(signature = "a{sv}")]
#[allow(dead_code)]
pub struct OpenFileOptions {
    accept_label: Option<String>,
    modal: Option<bool>,
    multiple: Option<bool>,
    directory: Option<bool>,
    filters: Option<Filters>,
    current_filter: Option<Filter>,
    choices: Option<Choices>,
    current_folder: Option<Vec<u8>>,
}

impl From<OpenFileOptions> for RunnerOpenFileOptions {
    fn from(options: OpenFileOptions) -> Self {
        Self {
            multiple: options.multiple.unwrap_or(false),
            directory: options.directory.unwrap_or(false),
        }
    }
}

#[derive(zvariant::DeserializeDict, zvariant::Type, Clone, Debug)]
#[zvariant(signature = "a{sv}")]
#[allow(dead_code)]
pub struct SaveFileOptions {
    accept_label: Option<String>,
    modal: Option<bool>,
    filters: Option<Filters>,
    current_filter: Option<Filter>,
    choices: Option<Choices>,
    current_name: Option<String>,
    current_folder: Option<Vec<u8>>,
    current_file: Option<Vec<u8>>,
}

fn get_recommended_filepath(options: &SaveFileOptions) -> String {
    let current_folder = options
        .current_folder
        .as_ref()
        .map(|folder| String::from_utf8_lossy(folder.as_slice()).into_owned())
        .map(|folder| folder.trim_matches(char::from(0)).to_owned()) // remove null
        .unwrap_or_else(|| {
            std::env::current_dir()
                .unwrap()
                .to_string_lossy()
                .into_owned()
        });

    let current_name = options.current_name.as_deref().unwrap_or("untitled");

    let mut save_file_path = std::path::PathBuf::from(&current_folder).join(&current_name);
    while save_file_path.exists() {
        let new_name = format!("{}_", save_file_path.file_stem().unwrap().to_string_lossy());
        save_file_path.set_file_name(new_name);
    }

    save_file_path.to_string_lossy().into_owned()
}

impl From<SaveFileOptions> for RunnerSaveFileOptions {
    fn from(options: SaveFileOptions) -> Self {
        Self {
            recommended_path: get_recommended_filepath(&options),
        }
    }
}

#[derive(zvariant::DeserializeDict, zvariant::Type, Clone, Debug)]
#[zvariant(signature = "a{sv}")]
#[allow(dead_code)]
pub struct SaveFilesOptions {
    accept_label: Option<String>,
    modal: Option<bool>,
    choices: Option<Choices>,
    current_folder: Option<Vec<u8>>,
    files: Option<Vec<Vec<u8>>>,
}

impl From<SaveFilesOptions> for RunnerSaveFilesOptions {
    fn from(options: SaveFilesOptions) -> Self {
        Self {
            current_folder: options
                .current_folder
                .map(|folder| String::from_utf8_lossy(folder.as_slice()).into_owned()),
            files: options
                .files
                .map(|files| {
                    files
                        .into_iter()
                        .map(|file| String::from_utf8_lossy(file.as_slice()).into_owned())
                        .collect()
                })
                .unwrap_or_default(),
        }
    }
}

#[derive(zvariant::SerializeDict, zvariant::Type, Debug, Default)]
#[zvariant(signature = "a{sv}")]
pub struct FileChooserResult {
    pub uris: Vec<String>,
    pub choices: Vec<(String, String)>,
    pub current_filter: Option<Filter>,
}

impl From<RunnerResult> for FileChooserResult {
    fn from(result: RunnerResult) -> Self {
        let uris = result.uris;

        Self {
            uris,
            ..Default::default()
        }
    }
}

impl From<Result<RunnerResult>> for PortalResponse<FileChooserResult> {
    fn from(res: Result<RunnerResult>) -> Self {
        match res {
            Ok(res) => {
                let res: FileChooserResult = res.into();
                if res.uris.is_empty() {
                    Self::Cancelled
                } else {
                    Self::Success(res)
                }
            }
            Err(err) => {
                tracing::error!("Error: {:?}", err);
                Self::Other
            }
        }
    }
}

#[derive(Debug)]
pub struct FileChooser {
    runner: Box<dyn Runner>,
}

const SAVE_FILE_TEMPLATE: &str = include_str!("../data/save_file_template.txt");
impl FileChooser {
    pub fn new(runner: Box<dyn Runner>) -> Self {
        Self { runner }
    }

    fn write_save_file_template(save_file_path: &std::path::Path) -> Result<()> {
        // make parent dir
        if let Some(parent_dir) = save_file_path.parent() {
            std::fs::create_dir_all(parent_dir).with_context(|| {
                format!(
                    "Failed to create parent directory of save file template {}",
                    parent_dir.display()
                )
            })?;
        }

        std::fs::write(save_file_path, SAVE_FILE_TEMPLATE).with_context(|| {
            format!(
                "Failed to write save file template to {}",
                save_file_path.display()
            )
        })
    }
}

#[zbus::interface(name = "org.freedesktop.impl.portal.FileChooser")]
impl FileChooser {
    #[tracing::instrument]
    async fn open_file(
        &self,
        handle: zvariant::ObjectPath<'_>,
        app_id: &str,
        parent_window: &str,
        title: &str,
        options: OpenFileOptions,
    ) -> PortalResponse<FileChooserResult> {
        self.runner
            .run_open_file(&RunnerOpenFileOptions::from(options))
            .into()
    }

    #[tracing::instrument]
    async fn save_file(
        &self,
        handle: zvariant::ObjectPath<'_>,
        app_id: &str,
        parent_window: &str,
        title: &str,
        options: SaveFileOptions,
    ) -> PortalResponse<FileChooserResult> {
        let options = RunnerSaveFileOptions::from(options);
        let save_file_path = std::path::PathBuf::from(options.recommended_path.clone());

        if let Err(e) = Self::write_save_file_template(&save_file_path) {
            tracing::error!("Failed to write temporary save file. Error: {:?}", e);
            return PortalResponse::Other;
        }

        let res = self
            .runner
            .run_save_file(&RunnerSaveFileOptions::from(options))
            .into();

        if let Err(e) = std::fs::remove_file(save_file_path) {
            tracing::error!("Failed to remove temporary save file. Error: {:?}", e);
        }

        res
    }

    #[tracing::instrument]
    async fn save_files(
        &self,
        handle: zvariant::ObjectPath<'_>,
        app_id: &str,
        parent_window: &str,
        title: &str,
        options: SaveFilesOptions,
    ) -> PortalResponse<FileChooserResult> {
        // TODO: is this enough?
        self.runner
            .run_save_files(&RunnerSaveFilesOptions::from(options))
            .into()
    }
}

mod config;
mod file_chooser;
mod runner;

use std::{error::Error, path::PathBuf};

use anyhow::{Context, Result};
use clap::Parser;
use file_chooser::FileChooser;
use runner::ConfigRunner;
use tracing::level_filters::LevelFilter;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter, Registry};
use tracing_tree::HierarchicalLayer;
use zbus::connection;

use crate::config::Config;

pub(crate) fn setup_tracing() -> Result<()> {
    let env_filter = EnvFilter::builder()
        .with_default_directive(LevelFilter::INFO.into())
        .from_env_lossy()
        .add_directive("zbus=error".parse()?);

    Registry::default()
        .with(env_filter)
        .with(
            HierarchicalLayer::new(2)
                .with_targets(true)
                .with_bracketed_fields(true),
        )
        .init();

    Ok(())
}

#[derive(Debug, clap::Parser)]
struct Args {
    #[arg(short, long)]
    config_path: Option<String>,
}

fn load_config(args: &Args) -> Result<config::Config> {
    let xdg_dirs = xdg::BaseDirectories::with_prefix("termfilepickers")?;
    let config_path = {
        let user_path = args.config_path.as_deref();
        if let Some(path) = user_path {
            PathBuf::from(path)
        } else {
            xdg_dirs
                .find_config_file("config.toml")
                .ok_or(anyhow::anyhow!(
                    "Config file not found. Use --config-path to specify the path"
                ))?
        }
    };

    tracing::info!("Loading config from {:?}", config_path);
    let content = std::fs::read_to_string(&config_path).context("Failed to read config file")?;

    toml::from_str(&content)
        .context("Failed to parse config file")
        .and_then(Config::validate)
        .context("Failed to validate config")
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    setup_tracing()?;

    let config = load_config(&Args::parse())?;
    let runner = Box::new(ConfigRunner::new(config));
    let picker = FileChooser::new(runner);

    let _conn = connection::Builder::session()?
        .name("org.freedesktop.impl.portal.desktop.termfilepickers")
        .context("Failed to create dbus connection")?
        .serve_at("/org/freedesktop/portal/desktop", picker)
        .context("Failed to serve dbus service")?
        .build()
        .await
        .context("Failed to build dbus connection")?;

    log::info!("Service started");

    std::future::pending::<()>().await;

    Ok(())
}

use std::{
    os::unix::fs::PermissionsExt,
    path::{Path, PathBuf},
};

use anyhow::{bail, Result};

#[derive(Debug, serde::Deserialize, serde::Serialize)]
pub struct Config {
    pub open_file_script_path: PathBuf,
    pub save_file_script_path: PathBuf,
    pub save_files_script_path: PathBuf,

    pub terminal_command: Vec<String>,
}

impl Config {
    /// Check if a script is valid by checking if it is a file that is executable.
    fn is_valid_script(script_path: &Path) -> Result<()> {
        if !script_path.is_file() {
            bail!("Not a file: {:?}", script_path);
        }

        if let Ok(metadata) = script_path.metadata() {
            if metadata.permissions().mode() & 0o111 == 0 {
                bail!("Not executable: {:?}", script_path);
            }
        }
        Ok(())
    }

    pub fn validate(self) -> Result<Self> {
        Self::is_valid_script(&self.open_file_script_path)?;
        Self::is_valid_script(&self.save_file_script_path)?;
        Self::is_valid_script(&self.save_files_script_path)?;

        Ok(self)
    }
}

use crate::config::{self, Config};

use anyhow::{Context, Result};
use tempfile::NamedTempFile;

const FILE_PROTOCOL: &str = "file://";

fn temp_path() -> String {
    NamedTempFile::new()
        .expect("Failed to create temp file")
        .into_temp_path()
        .to_string_lossy()
        .to_string()
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct RunnerOpenFileOptions {
    pub multiple: bool,
    pub directory: bool,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct RunnerSaveFileOptions {
    pub recommended_path: String,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct RunnerSaveFilesOptions {
    pub current_folder: Option<String>,
    pub files: Vec<String>,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
#[serde(tag = "type")]
enum SpecificRunnerArguments {
    OpenFile(RunnerOpenFileOptions),
    SaveFile(RunnerSaveFileOptions),
    SaveFiles(RunnerSaveFilesOptions),
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
struct RunnerArguments {
    #[serde(flatten)]
    specific: SpecificRunnerArguments,
    out_file: String,
    termcmd: Vec<String>,
}

impl RunnerArguments {
    fn new(config: &Config, specific: SpecificRunnerArguments) -> Self {
        Self {
            specific,
            out_file: temp_path(),
            termcmd: config.terminal_command.clone(),
        }
    }
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct RunnerResult {
    // for now, only support uris. TODO: filters?
    pub uris: Vec<String>,
}

pub trait Runner: std::fmt::Debug + Send + Sync {
    fn run_open_file(&self, options: &RunnerOpenFileOptions) -> Result<RunnerResult>;
    fn run_save_file(&self, options: &RunnerSaveFileOptions) -> Result<RunnerResult>;
    fn run_save_files(&self, options: &RunnerSaveFilesOptions) -> Result<RunnerResult>;
}

#[derive(Debug)]
pub struct ConfigRunner {
    config: config::Config,
}

impl ConfigRunner {
    pub(crate) fn new(config: config::Config) -> Self {
        Self { config }
    }

    fn parse_result(out_file: &str) -> Result<RunnerResult> {
        let content = std::fs::read_to_string(out_file)?;

        // newline separated list of files
        let uris = content
            .lines()
            .map(str::to_string)
            .map(|uri| {
                if uri.starts_with(FILE_PROTOCOL) {
                    uri
                } else {
                    format!("{}{}", FILE_PROTOCOL, uri)
                }
            })
            .collect();

        Ok(RunnerResult { uris })
    }

    #[tracing::instrument(skip(options))]
    fn run_script(
        script_path: &std::path::Path,
        options: &RunnerArguments,
    ) -> Result<RunnerResult> {
        let out = std::process::Command::new(script_path)
            .arg(serde_json::to_string(options)?)
            .output()?;

        if !out.status.success() {
            anyhow::bail!("Runner failed: {:?}", out);
        }

        Self::parse_result(&options.out_file).with_context(|| {
            format!(
                "Script did not produce a valid output file: {}.\n
                     Script standard output was: {:?}",
                options.out_file, out
            )
        })
    }
}

impl Runner for ConfigRunner {
    fn run_open_file(&self, options: &RunnerOpenFileOptions) -> Result<RunnerResult> {
        let args = RunnerArguments::new(
            &self.config,
            SpecificRunnerArguments::OpenFile(options.clone()),
        );
        Self::run_script(&self.config.open_file_script_path, &args)
    }

    fn run_save_file(&self, options: &RunnerSaveFileOptions) -> Result<RunnerResult> {
        let args = RunnerArguments::new(
            &self.config,
            SpecificRunnerArguments::SaveFile(options.clone()),
        );
        Self::run_script(&self.config.save_file_script_path, &args)
    }

    fn run_save_files(&self, options: &RunnerSaveFilesOptions) -> Result<RunnerResult> {
        let args = RunnerArguments::new(
            &self.config,
            SpecificRunnerArguments::SaveFiles(options.clone()),
        );
        Self::run_script(&self.config.save_files_script_path, &args)
    }
}
